function freshBotName(roster, base = "New Bot") {
  const taken = new Set(roster.bots.map((bot) => bot.name.toLowerCase()));
  if (!taken.has(base.toLowerCase())) return base;
  let index = 2;
  while (taken.has(`${base.toLowerCase()} ${index}`)) index += 1;
  return `${base} ${index}`;
}
